    private val scriptTable: IntArray by lazy {
        val parts = SCRIPT_RANGES.split(';')
        val out = IntArray(parts.size * 3)
        var n = 0
        for (part in parts) { val f = part.split(','); out[n++] = f[0].toInt(16); out[n++] = f[1].toInt(16); out[n++] = f[2].toInt(16) }
        out
    }
    const val SCRIPT_COUNT = 171
    fun scriptOf(codePoint: Int): Int {
        val t = scriptTable
        var a = 0
        var b = t.size / 3
        while (a < b) {
            val m = (a + b) ushr 1
            if (codePoint < t[3 * m]) b = m
            else if (codePoint > t[3 * m + 1]) a = m + 1
            else return t[3 * m + 2]
        }
        return -1
    }

    // The language of every script in use today (CLDR's likely subtags of the
    // UAX #31 Recommended and Limited_Use scripts): the codes the detector can
    // name a span after its script. IsoCodes knows a three-letter one by itself.
